SQL_DOC.P_SQL:
DECLARE
V_COUNT NUMBER;
BEGIN SELECT COUNT(*) INTO V_COUNT FROM V_KEP_INV WHERE DLVY_NO = $DLVY_NO$ AND PO_NO = $PO_NO$ AND PO_LNNO = $PO_LNNO$ ;
IF V_COUNT = 0 THEN
INSERT INTO V_KEP_INV( PLANT , DLVY_NO , PO_NO , PO_LNNO , STATUS , DLVY_DUE_DATE , PRCH_UNT_PR , DLVY_DUE_QTY , DLVY_AMT , POR_NO , POR_LNNO , REMARK , IF_DATE , IF_FLAG , RGST_USER_ID , MNT_USER_ID )VALUES( $PLANT$ , $DLVY_NO$ , $PO_NO$ , $PO_LNNO$ , $STATUS$ , $DLVY_DUE_DATE$ , $PRCH_UNT_PR$ , $DLVY_DUE_QTY$ , $DLVY_AMT$ , $POR_NO$ , $POR_LNNO$ , nvl( $REMARK$ ,' ') , SYSDATE , 'N' , ' ' , ' '); ELSE UPDATE V_KEP_INV SET STATUS = $STATUS$ , DLVY_DUE_DATE = $DLVY_DUE_DATE$ , DLVY_DUE_QTY = $DLVY_DUE_QTY$ , REMARK = $REMARK$ , IF_FLAG = 'N' , IF_DATE = SYSDATE WHERE DLVY_NO = $DLVY_NO$ ; END IF; END;
